const TOK=$('Init Seats').first().json.run_token;const RT=' run_token='+TOK;
// D1: DEFENDER ROUND 1, OPENING. Body built by API family; model from model_config by seat.
const FAMS=['anthropic','openai','gemini','grok','mimo','openrouter','deepseek'];
const bodyFor=(fam,model,tok,sys,msgs)=>{
 if(fam==='anthropic')return {model,max_tokens:tok,system:[{type:'text',text:sys,cache_control:{type:'ephemeral',ttl:'1h'}}],messages:msgs};
 if(fam==='gemini')return {systemInstruction:{parts:[{text:sys}]},contents:msgs.map(m=>({role:m.role==='assistant'?'model':'user',parts:[{text:m.content}]})),generationConfig:{maxOutputTokens:tok}};
 const m=[{role:'system',content:sys},...msgs];
 if(fam==='openai')return {model,max_completion_tokens:tok,messages:m};
 // ORDER J (BB-6200): glm debates at reasoning effort medium, as qwen does; at max it returned no text (ODV1-26217 C1, ODV1-26238 C3).
 if(fam==='openrouter')return {model,max_tokens:tok,reasoning:{effort:/^(?:qwen\/|z-ai\/glm-)/.test(model)?'medium':'max'},messages:m};
 return {model,max_tokens:tok,messages:m};};
const I=$('Init with Guards').first().json;const R=$('Resolve Seats').first().json;
const call=(seat,sys,msgs)=>{const idx=FAMS.indexOf(seat.fam);if(idx<0)throw new Error('ORACLE_DEBATE_V1: no call path for family '+seat.fam+RT);return {fam:seat.fam,fam_idx:idx,model:seat.model,body:bodyFor(seat.fam,seat.model,seat.tok,sys,msgs)};};
const DD=`\n\n=== DEFENSE DISCIPLINE (Eric-ruled 2026-07-18; protocol_debate_engine DD-1..DD-3) ===\n\nDD-1. SCOPE VS AMMUNITION. The debate's scope is the question and its citation CHAIN; the verse is ammunition, not the battlefield. A challenger's point about an isolated term or verse is answered by re-seating that term in its chain — context, grammar floor, cross-reference — never by adjudicating the term in isolation. A term stripped of its chain proves nothing and concedes nothing.\n\nDD-2. NO IN-ROUND CONCESSION. No concession, re-grade, or framework adjustment is ever made on the opponent's clock. The only in-battle response to a correction — however textually accurate — is: "Noted. Not conceding here. Goes to review." All self-examination happens in cold review: full record, our ground, opponent not in the room. A defense that concedes in-round to a context-stripped term is a defense-discipline slip and must be flagged in review even when the verdict still lands HELD.\n\nDD-3. CHAIN-SCOPED FRAMING — Isaiah 28:10 as rule of engagement. Debate topics are framed at the chain level: the framework's case is its interlocking citations — precept upon precept, line upon line, here a little, there a little — and the challenger must break the CHAIN, not one link. Isaiah 28:10 is declared in the topic framing as the rule of engagement; it is never cited inside L3 as a witness for a conclusion — that is citing the method as evidence, and DG-29 cuts both ways.`;const sys=I.dsys+DD;const msgs=[{role:'user',content:'DEBATE TOPIC: '+I.topic+'\n\nOpen the debate. Full L1-L2-L3. Tag every claim.\n\nEND your opening with a section titled exactly DECLARED CHAIN -- the links your case stands on: a numbered list, MINIMUM 3 and MAXIMUM 6, one line per link, no commentary after the list. Each line gives the claim and the footing it exhibits. Every declared link carries the floor at declaration: it counts as evidence only if it rests on -- and exhibits -- AT LEAST TWO prior layers of footing: a stating [L1] verse, an [L2] lexical ground, or an [L3] cross-reference. It must show the chain from each exhibited footing to the inference (precept upon precept, line upon line). A link declared with fewer than two exhibited prior layers floats free, and your opponent will name it. THE LAST NUMBERED LINE IS THE ANSWER TO THE TOPIC QUESTION -- the conclusion the other links carry. You cannot decline to have one and you cannot move it. This list is your chain: the challenger attacks it by number, and every later round is scored against it.'}];
return [{json:{run_token:TOK,round:'D1',call:call(R.defender,sys,msgs)}}];
